int star_usable = 0, triad_usable = 0;
adcs_quat_t star_q = {1,0,0,0}, triad_q = {1,0,0,0};
double star_res = 0.0, triad_res = 0.0;
rs_source_t chosen = RS_NONE;
adcs_quat_t selected = {1,0,0,0}, blended = {1,0,0,0};
double disagreement = 0.0;
double sw = 0.0, tw = 0.0;

/* 1. 配置合法性校验 */
if (!((rs_config.enable == 0) || (rs_config.enable == 1)) ||
    !(isfinite(rs_config.max_residual_rad) && rs_config.max_residual_rad >= 0.0) ||
    !(isfinite(rs_config.fuse_angle_rad) && rs_config.fuse_angle_rad >= 0.0 &&
      rs_config.fuse_angle_rad <= ADCS_PI) ||
    !(isfinite(rs_config.switch_margin_rad) && rs_config.switch_margin_rad >= 0.0) ||
    !(isfinite(rs_config.residual_weight_floor_rad) && rs_config.residual_weight_floor_rad > 0.0) ||
    !(isfinite(rs_config.output_alpha) && rs_config.output_alpha > 0.0 && rs_config.output_alpha <= 1.0) ||
    (rs_config.switch_confirm_cycles < 1U) || (rs_config.switch_confirm_cycles > 20U) ||
    (rs_config.max_outage_cycles < 1U) || (rs_config.max_outage_cycles > 20U)) {
    rs_output.source = RS_FAULT;
    rs_output.primary = rs_state.primary;
    rs_output.candidate = rs_state.candidate;
    rs_output.candidate_good = rs_state.candidate_good;
    rs_output.outage = rs_state.outage;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1,0,0,0};
    return;
}

/* 2. disable 复位 */
if (rs_config.enable == 0) {
    rs_state.primary = RS_NONE;
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
    rs_state.outage = 0U;
    rs_state.previous_q_bi = (adcs_quat_t){1,0,0,0};
    rs_output.source = RS_NONE;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0U;
    rs_output.outage = 0U;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1,0,0,0};
    return;
}

/* 3. 计算各源可用性与归一化 */
star_res = rs_input.star_residual_rad;
triad_res = rs_input.triad_residual_rad;
if (rs_input.star_q_bi != NULL) {
    if ((adcs_quat_normalize(rs_input.star_q_bi, &star_q) == ADCS_OK) &&
        isfinite(star_res) && star_res >= 0.0 && star_res <= rs_config.max_residual_rad) {
        star_usable = 1;
    }
}
if (rs_input.triad_q_bi != NULL) {
    if ((adcs_quat_normalize(rs_input.triad_q_bi, &triad_q) == ADCS_OK) &&
        isfinite(triad_res) && triad_res >= 0.0 && triad_res <= rs_config.max_residual_rad) {
        triad_usable = 1;
    }
}

/* 4. 无 primary 时选 primary */
if ((rs_state.primary != RS_STAR) && (rs_state.primary != RS_TRIAD)) {
    if (star_usable) {
        rs_state.primary = RS_STAR;
    } else if (triad_usable) {
        rs_state.primary = RS_TRIAD;
    } else {
        rs_state.primary = RS_NONE;
    }
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
}

/* 5. 主源维护/切换证据 */
{
    int primary_usable = 0;
    rs_source_t other = RS_NONE;
    int other_usable = 0;
    if (rs_state.primary == RS_STAR) {
        primary_usable = star_usable;
        other = RS_TRIAD;
        other_usable = triad_usable;
    } else if (rs_state.primary == RS_TRIAD) {
        primary_usable = triad_usable;
        other = RS_STAR;
        other_usable = star_usable;
    } else {
        primary_usable = 0;
        other = RS_NONE;
        other_usable = 0;
    }

    if (primary_usable && other_usable) {
        double prim_res = (rs_state.primary == RS_STAR) ? star_res : triad_res;
        double oth_res = (other == RS_STAR) ? star_res : triad_res;
        if (oth_res + rs_config.switch_margin_rad <= prim_res) {
            if (rs_state.candidate == other) {
                if (rs_state.candidate_good < rs_config.switch_confirm_cycles) {
                    rs_state.candidate_good++;
                }
            } else {
                rs_state.candidate = other;
                rs_state.candidate_good = 1U;
            }
            if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
                rs_state.primary = other;
                rs_state.candidate = RS_NONE;
                rs_state.candidate_good = 0U;
            }
        } else {
            rs_state.candidate = RS_NONE;
            rs_state.candidate_good = 0U;
        }
    } else if (primary_usable && !other_usable) {
        rs_state.candidate = RS_NONE;
        rs_state.candidate_good = 0U;
    } else if (!primary_usable && other_usable) {
        rs_state.primary = other;
        rs_state.candidate = RS_NONE;
        rs_state.candidate_good = 0U;
    } else {
        rs_state.candidate = RS_NONE;
        rs_state.candidate_good = 0U;
    }
}

/* 6. sign-invariant disagreement angle */
if (star_usable && triad_usable) {
    double dot = star_q.w * triad_q.w + star_q.x * triad_q.x + star_q.y * triad_q.y + star_q.z * triad_q.z;
    dot = fabs(dot);
    if (dot > 1.0) dot = 1.0;
    disagreement = 2.0 * acos(dot);
} else {
    disagreement = 0.0;
}

/* 7. 选择输出源 / 融合 */
if (star_usable && triad_usable && disagreement <= rs_config.fuse_angle_rad) {
    adcs_quat_t triad_aligned = triad_q;
    double d = star_q.w * triad_q.w + star_q.x * triad_q.x + star_q.y * triad_q.y + star_q.z * triad_q.z;
    if (d < 0.0) {
        triad_aligned.w = -triad_q.w;
        triad_aligned.x = -triad_q.x;
        triad_aligned.y = -triad_q.y;
        triad_aligned.z = -triad_q.z;
    }
    sw = 1.0 / (rs_config.residual_weight_floor_rad + star_res);
    tw = 1.0 / (rs_config.residual_weight_floor_rad + triad_res);
    {
        double wsum = sw + tw;
        adcs_quat_t wq;
        wq.w = (sw / wsum) * star_q.w + (tw / wsum) * triad_aligned.w;
        wq.x = (sw / wsum) * star_q.x + (tw / wsum) * triad_aligned.x;
        wq.y = (sw / wsum) * star_q.y + (tw / wsum) * triad_aligned.y;
        wq.z = (sw / wsum) * star_q.z + (tw / wsum) * triad_aligned.z;
        if (adcs_quat_normalize(&wq, &selected) != ADCS_OK) {
            selected = star_q;
        }
    }
    chosen = RS_FUSED;
} else if (rs_state.primary == RS_STAR && star_usable) {
    selected = star_q;
    chosen = RS_STAR;
    sw = 1.0 / (rs_config.residual_weight_floor_rad + star_res);
    tw = 0.0;
} else if (rs_state.primary == RS_TRIAD && triad_usable) {
    selected = triad_q;
    chosen = RS_TRIAD;
    sw = 0.0;
    tw = 1.0 / (rs_config.residual_weight_floor_rad + triad_res);
} else if (star_usable) {
    selected = star_q;
    chosen = RS_STAR;
    sw = 1.0 / (rs_config.residual_weight_floor_rad + star_res);
    tw = 0.0;
} else if (triad_usable) {
    selected = triad_q;
    chosen = RS_TRIAD;
    sw = 0.0;
    tw = 1.0 / (rs_config.residual_weight_floor_rad + triad_res);
} else {
    chosen = RS_NONE;
    sw = 0.0;
    tw = 0.0;
}

/* 8. 无可用源：NONE/identity、outage、latch FAULT */
if (chosen == RS_NONE) {
    rs_state.outage++;
    rs_output.source = (rs_state.outage >= rs_config.max_outage_cycles) ? RS_FAULT : RS_NONE;
    rs_output.primary = rs_state.primary;
    rs_output.candidate = rs_state.candidate;
    rs_output.candidate_good = rs_state.candidate_good;
    rs_output.outage = rs_state.outage;
    rs_output.disagreement_rad = disagreement;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1,0,0,0};
    return;
}

/* 9. 符号对齐 + blend + normalize */
rs_state.outage = 0U;
{
    double dprev = rs_state.previous_q_bi.w * selected.w + rs_state.previous_q_bi.x * selected.x +
                   rs_state.previous_q_bi.y * selected.y + rs_state.previous_q_bi.z * selected.z;
    if (dprev < 0.0) {
        selected.w = -selected.w;
        selected.x = -selected.x;
        selected.y = -selected.y;
        selected.z = -selected.z;
    }
    blended.w = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.w + rs_config.output_alpha * selected.w;
    blended.x = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.x + rs_config.output_alpha * selected.x;
    blended.y = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.y + rs_config.output_alpha * selected.y;
    blended.z = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.z + rs_config.output_alpha * selected.z;
    if (adcs_quat_normalize(&blended, &rs_output.q_bi) != ADCS_OK) {
        rs_output.q_bi = selected;
    }
}
rs_state.previous_q_bi = rs_output.q_bi;

/* 10. 发布字段 */
rs_output.source = chosen;
rs_output.primary = rs_state.primary;
rs_output.candidate = rs_state.candidate;
rs_output.candidate_good = rs_state.candidate_good;
rs_output.outage = rs_state.outage;
rs_output.disagreement_rad = disagreement;
rs_output.star_weight = sw;
rs_output.triad_weight = tw;

