    if ((adcs_quat_normalize(rs_input.triad_q_bi, &triad_q) == ADCS_OK) &&
        isfinite(triad_res) && triad_res >= 0.0 && triad_res <= rs_config.max_residual_rad) {
        triad_usable = 1;
    }
}

