        double wsum = sw + tw;
        adcs_quat_t wq;
        wq.w = (sw / wsum) * star_q.w + (tw / wsum) * triad_aligned.w;
        wq.x = (sw / wsum) * star_q.x + (tw / wsum) * triad_aligned.x;
        wq.y = (sw / wsum) * star_q.y + (tw / wsum) * triad_aligned.y;
        wq.z = (sw / wsum) * star_q.z + (tw / wsum) * triad_aligned.z;
