/* 8. 无可用源：NONE/identity、outage、latch FAULT */
if (chosen == RS_NONE) {
    rs_state.outage++;
    rs_output.source = (rs_state.outage >= rs_config.max_outage_cycles) ? RS_FAULT : RS_NONE;
    rs_output.primary = rs_state.primary;
    rs_output.candidate = rs_state.candidate;
    rs_output.candidate_good = rs_state.candidate_good;
    rs_output.outage = rs_state.outage;
    rs_output.disagreement_rad = disagreement;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1,0,0,0};
