    blended.y = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.y + rs_config.output_alpha * selected.y;
    blended.z = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.z + rs_config.output_alpha * selected.z;
    if (adcs_quat_normalize(&blended, &rs_output.q_bi) != ADCS_OK) {
        rs_output.q_bi = selected;
    }
}
