int star_ok = 0, triad_ok = 0;
adcs_quat_t star_q, triad_q;
double star_res = 0.0, triad_res = 0.0;
adcs_quat_t selected;
double disagreement = 0.0;
double w_star = 0.0, w_triad = 0.0;
int valid_cfg = 1;

/* defaults */
rs_output.source = RS_NONE;
rs_output.primary = rs_state.primary;
rs_output.candidate = rs_state.candidate;
rs_output.candidate_good = rs_state.candidate_good;
rs_output.outage = rs_state.outage;
rs_output.disagreement_rad = 0.0;
rs_output.star_weight = 0.0;
rs_output.triad_weight = 0.0;
rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};

/* Step 1: validate configuration */
if ((rs_config.enable != 0 && rs_config.enable != 1) ||
    (!isfinite(rs_config.max_residual_rad)) || (rs_config.max_residual_rad < 0.0) ||
    (!isfinite(rs_config.fuse_angle_rad)) || (rs_config.fuse_angle_rad < 0.0) ||
    (rs_config.fuse_angle_rad > ADCS_PI) ||
    (!isfinite(rs_config.switch_margin_rad)) || (rs_config.switch_margin_rad < 0.0) ||
    (!isfinite(rs_config.residual_weight_floor_rad)) || (rs_config.residual_weight_floor_rad <= 0.0) ||
    (!isfinite(rs_config.output_alpha)) || (rs_config.output_alpha <= 0.0) ||
    (rs_config.output_alpha > 1.0) ||
    (rs_config.switch_confirm_cycles < 1U) || (rs_config.switch_confirm_cycles > 20U) ||
    (rs_config.max_outage_cycles < 1U) || (rs_config.max_outage_cycles > 20U)) {
    valid_cfg = 0;
}
if (!valid_cfg) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0U;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    rs_state.primary = RS_NONE;
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
    rs_state.previous_q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

/* Disable resets */
if (rs_config.enable == 0) {
    rs_state.primary = RS_NONE;
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
    rs_state.outage = 0U;
    rs_state.previous_q_bi = (adcs_quat_t){1, 0, 0, 0};
    rs_output.source = RS_NONE;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0U;
    rs_output.outage = 0U;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

/* Latched FAULT persists */
if (rs_output.source == RS_FAULT) {
    rs_output.source = RS_FAULT;
    rs_output.primary = rs_state.primary;
    rs_output.candidate = rs_state.candidate;
    rs_output.candidate_good = rs_state.candidate_good;
    rs_output.outage = rs_state.outage;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    rs_state.previous_q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

/* Step 3: usability */
if (rs_input.star_q_bi != NULL) {
    if (adcs_quat_normalize(rs_input.star_q_bi, &star_q) == ADCS_OK) {
        star_res = rs_input.star_residual_rad;
        if (isfinite(star_res) && star_res >= 0.0 && star_res <= rs_config.max_residual_rad)
            star_ok = 1;
    }
}
if (rs_input.triad_q_bi != NULL) {
    if (adcs_quat_normalize(rs_input.triad_q_bi, &triad_q) == ADCS_OK) {
        triad_res = rs_input.triad_residual_rad;
        if (isfinite(triad_res) && triad_res >= 0.0 && triad_res <= rs_config.max_residual_rad)
            triad_ok = 1;
    }
