if (rs_state.primary == RS_NONE) {
    if (star_ok) {
        rs_state.primary = RS_STAR;
    } else if (triad_ok) {
        rs_state.primary = RS_TRIAD;
    }
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
} else {
    rs_source_t primary = rs_state.primary;
    int primary_ok = (primary == RS_STAR) ? star_ok : triad_ok;
    rs_source_t other = (primary == RS_STAR) ? RS_TRIAD : RS_STAR;
    int other_ok = (other == RS_STAR) ? star_ok : triad_ok;
    double primary_res = (primary == RS_STAR) ? star_res : triad_res;
    double other_res = (other == RS_STAR) ? star_res : triad_res;
    if (!primary_ok) {
        if (other_ok) {
            rs_state.primary = other;
        }
        rs_state.candidate = RS_NONE;
        rs_state.candidate_good = 0U;
    } else if (other_ok) {
        if ((primary_res - other_res) >= rs_config.switch_margin_rad) {
            rs_state.candidate = other;
            rs_state.candidate_good++;
            if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
                rs_state.primary = other;
                rs_state.candidate = RS_NONE;
                rs_state.candidate_good = 0U;
            }
        } else {
            rs_state.candidate = RS_NONE;
            rs_state.candidate_good = 0U;
        }
    } else {
        rs_state.candidate = RS_NONE;
        rs_state.candidate_good = 0U;
    }
}

/* Step 5: disagreement */
if (star_ok && triad_ok) {
    double d = adcs_quat_abs_dot(&star_q, &triad_q);
    if (d > 1.0) d = 1.0;
    if (d < -1.0) d = -1.0;
    disagreement = acos(d);
}

/* Step 6: publish selection */
if (star_ok && triad_ok && disagreement <= rs_config.fuse_angle_rad) {
    adcs_quat_t triad_aligned = triad_q;
    adcs_quat_t fused;
    double dot_st = star_q.w * triad_q.w + star_q.x * triad_q.x +
                    star_q.y * triad_q.y + star_q.z * triad_q.z;
    if (dot_st < 0.0) {
        triad_aligned.w = -triad_aligned.w;
        triad_aligned.x = -triad_aligned.x;
        triad_aligned.y = -triad_aligned.y;
        triad_aligned.z = -triad_aligned.z;
    }
    w_star = 1.0 / (rs_config.residual_weight_floor_rad + star_res);
    w_triad = 1.0 / (rs_config.residual_weight_floor_rad + triad_res);
    fused.w = w_star * star_q.w + w_triad * triad_aligned.w;
    fused.x = w_star * star_q.x + w_triad * triad_aligned.x;
    fused.y = w_star * star_q.y + w_triad * triad_aligned.y;
    fused.z = w_star * star_q.z + w_triad * triad_aligned.z;
    (void)adcs_quat_normalize(&fused, &selected);
    rs_output.source = RS_FUSED;
} else if (rs_state.primary == RS_STAR && star_ok) {
    selected = star_q;
    rs_output.source = RS_STAR;
} else if (rs_state.primary == RS_TRIAD && triad_ok) {
    selected = triad_q;
    rs_output.source = RS_TRIAD;
} else if (star_ok) {
    selected = star_q;
    rs_output.source = RS_STAR;
} else if (triad_ok) {
    selected = triad_q;
    rs_output.source = RS_TRIAD;
} else {
    selected = (adcs_quat_t){1, 0, 0, 0};
    rs_output.source = RS_NONE;
    rs_state.outage++;
    if (rs_state.outage >= rs_config.max_outage_cycles) {
        rs_output.source = RS_FAULT;
    }
}

/* Step 7: sign-align and blend */
if (rs_output.source == RS_NONE || rs_output.source == RS_FAULT) {
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    rs_state.previous_q_bi = rs_output.q_bi;
} else {
    adcs_quat_t prev = rs_state.previous_q_bi;
    adcs_quat_t sel = selected;
    adcs_quat_t blended;
    double dot_ps = prev.w * sel.w + prev.x * sel.x + prev.y * sel.y + prev.z * sel.z;
    if (dot_ps < 0.0) {
        sel.w = -sel.w;
        sel.x = -sel.x;
        sel.y = -sel.y;
        sel.z = -sel.z;
    }
    blended.w = (1.0 - rs_config.output_alpha) * prev.w + rs_config.output_alpha * sel.w;
    blended.x = (1.0 - rs_config.output_alpha) * prev.x + rs_config.output_alpha * sel.x;
    blended.y = (1.0 - rs_config.output_alpha) * prev.y + rs_config.output_alpha * sel.y;
    blended.z = (1.0 - rs_config.output_alpha) * prev.z + rs_config.output_alpha * sel.z;
    (void)adcs_quat_normalize(&blended, &rs_output.q_bi);
    rs_state.previous_q_bi = rs_output.q_bi;
}

/* Step 8: outputs */
rs_output.primary = rs_state.primary;
rs_output.candidate = rs_state.candidate;
rs_output.candidate_good = rs_state.candidate_good;
rs_output.outage = rs_state.outage;
rs_output.disagreement_rad = disagreement;
rs_output.star_weight = w_star;
rs_output.triad_weight = w_triad;

